"""Phase 3: previews generated by background jobs. Media is synthetic; videos come from the local ffmpeg."""

import hashlib
import io
import json
import shutil
import subprocess
import sys

import numpy as np
import pytest
import rasterio
from PIL import Image
from rasterio.io import MemoryFile
from rasterio.transform import from_origin
from rasterio.windows import Window
from sqlalchemy import text

from geopoc.db.session import get_engine
from geopoc.storage import store
from tests import media
from tests.conftest import API_DIR, TEST_DATA_ROOT
from tests.test_assets import needs_ffmpeg, stored_files, upload


def raster_bytes(dtype="uint8", bands=1, size=(400, 300), crs="EPSG:32643", fill=None) -> bytes:
    rng = np.random.default_rng(5)
    if np.dtype(dtype).kind == "c":
        data = (rng.random((bands, size[1], size[0])) + 1j * rng.random((bands, size[1], size[0]))).astype(dtype)
    elif np.dtype(dtype).kind == "f":
        data = (rng.random((bands, size[1], size[0])) * 5000 - 100).astype(dtype)
    else:
        data = rng.integers(0, np.iinfo(dtype).max // 4, (bands, size[1], size[0])).astype(dtype)
    if fill is not None:
        data[:, :50, :50] = fill
    profile = {"driver": "GTiff", "width": size[0], "height": size[1], "count": bands, "dtype": dtype}
    if crs:
        profile |= {"crs": crs, "transform": from_origin(500000, 3000000, 10, 10)}
    with MemoryFile() as memory:
        with memory.open(**profile) as dst:
            dst.write(data)
        return memory.read()


def preview(client, asset_id, variant="view"):
    response = client.get(f"/api/v1/assets/{asset_id}/preview", params={"variant": variant})
    picture = Image.open(io.BytesIO(response.content)) if response.status_code == 200 else None
    return response, picture


def artifacts(asset_id) -> dict:
    with get_engine().connect() as conn:
        rows = conn.execute(
            text("SELECT variant, storage_path, width, height, sha256, details FROM artifact WHERE asset_id = :id"),
            {"id": asset_id},
        ).all()
    return {row[0]: row for row in rows}


# --- images --------------------------------------------------------------------------------------------------------


@pytest.mark.parametrize(("name", "fmt"), [("p.jpg", "JPEG"), ("p.png", "PNG"), ("p.webp", "WEBP")])
def test_image_preview_is_generated_by_a_job_and_leaves_the_original_untouched(
    client, project, headers, run_jobs, name, fmt
):
    data = media.image_bytes(fmt, size=(3000, 2000))
    asset = upload(client, project, headers, name, data).json()["asset"]

    # Uploading does not wait for the preview: it is queued.
    assert asset["preview"]["status"] == "pending" and asset["preview"]["variants"] == []
    waiting, _ = preview(client, asset["id"])
    assert waiting.status_code == 409 and waiting.json()["code"] == "PREVIEW_NOT_READY"

    assert run_jobs() == ["completed"]
    info = client.get(f"/api/v1/assets/{asset['id']}").json()["preview"]
    assert info == {
        "status": "ready",
        "variants": ["thumb", "view"],
        "job_id": asset["preview"]["job_id"],
        "error_code": None,
        "error_message": None,
    }

    response, view = preview(client, asset["id"])
    assert response.status_code == 200 and response.headers["content-type"] == "image/webp"
    assert view.format == "WEBP" and view.size == (1280, 853)  # same shape, longest side 1280
    _, thumb = preview(client, asset["id"], "thumb")
    assert thumb.size == (256, 171)

    stored = artifacts(asset["id"])
    assert set(stored) == {"view", "thumb"}
    assert stored["view"][1] == f"previews/{asset['id']}/view.webp"
    assert response.headers["etag"] == f'"{stored["view"][4]}"'
    assert stored["view"][5]["source_size"] == [3000, 2000]

    # The original is byte-identical, still read-only, and is the only file under originals/.
    (original,) = stored_files()
    assert hashlib.sha256(original.read_bytes()).hexdigest() == asset["sha256"] == hashlib.sha256(data).hexdigest()
    assert client.get(f"/api/v1/assets/{asset['id']}/content").content == data


def test_preview_keeps_transparency_and_small_images_are_not_enlarged(client, project, headers, run_jobs):
    buffer = io.BytesIO()
    Image.new("RGBA", (40, 30), (10, 200, 30, 120)).save(buffer, "PNG")
    asset = upload(client, project, headers, "alpha.png", buffer.getvalue()).json()["asset"]
    run_jobs()
    _, view = preview(client, asset["id"])
    assert view.size == (40, 30) and view.mode == "RGBA"


def test_preview_does_not_apply_exif_orientation(client, project, headers, run_jobs):
    """Previews stay in the original's pixel grid so that image-space overlays line up (the pixel convention)."""
    exif = Image.Exif()
    exif[274] = 6  # "rotate 90 degrees to display"
    data = media.image_bytes("JPEG", size=(200, 100), exif=exif)
    asset = upload(client, project, headers, "rotated.jpg", data).json()["asset"]
    run_jobs()
    _, view = preview(client, asset["id"])
    assert view.size == (200, 100)  # not (100, 200)
    assert asset["metadata"]["exif"]["orientation"] == 6  # the orientation is reported instead


# --- rasters ---------------------------------------------------------------------------------------------------------


def test_rgb_raster_preview_shows_values_as_stored(client, project, headers, run_jobs):
    asset = upload(
        client, project, headers, "rgb.tif", raster_bytes("uint8", bands=3, size=(2000, 1000)), "overhead_raster"
    ).json()["asset"]
    assert run_jobs() == ["completed", "completed"]  # preview, then band statistics
    _, view = preview(client, asset["id"])
    assert view.size == (1280, 640) and view.mode == "RGB"
    details = artifacts(asset["id"])["view"][5]
    assert details["bands_shown"] == [1, 2, 3]
    assert details["display_stretch"] == "none (8-bit values shown as stored)"
    assert "image space only" in details["georeferencing"]


@pytest.mark.parametrize("dtype", ["uint16", "int16", "float32"])
def test_non_8bit_raster_preview_records_how_brightness_was_rescaled(client, project, headers, run_jobs, dtype):
    asset = upload(client, project, headers, "dem.tif", raster_bytes(dtype), "overhead_raster").json()["asset"]
    assert run_jobs() == ["completed", "completed"]  # preview, then band statistics
    _, view = preview(client, asset["id"])
    assert view.size == (400, 300) and view.mode in ("L", "RGB")
    stretch = artifacts(asset["id"])["view"][5]["display_stretch"]
    assert "2nd and 98th percentile" in stretch["method"]
    assert stretch["bands"][0]["low"] < stretch["bands"][0]["high"]


def test_raster_with_nan_and_without_crs_still_previews_in_image_space(client, project, headers, run_jobs):
    data = raster_bytes("float32", crs=None, fill=np.nan)
    asset = upload(client, project, headers, "nocrs.tif", data, "overhead_raster").json()["asset"]
    assert asset["raster"]["georeferenced"] is False
    assert run_jobs() == ["completed", "completed"]  # preview, then band statistics
    response, view = preview(client, asset["id"])
    assert response.status_code == 200 and view.size == (400, 300)
    # A preview never creates georeferencing the original lacks.
    assert client.get(f"/api/v1/assets/{asset['id']}").json()["raster"]["footprint_4326"] is None


def test_unsupported_preview_format_fails_clearly_without_harming_the_asset(client, project, headers, run_jobs):
    asset = upload(client, project, headers, "complex.tif", raster_bytes("complex64"), "overhead_raster").json()[
        "asset"
    ]
    assert asset["status"] == "validated"  # ingestion accepts it; only the picture is not possible
    assert run_jobs() == ["failed", "failed"]  # preview and statistics: complex values unsupported

    after = client.get(f"/api/v1/assets/{asset['id']}").json()
    assert after["preview"]["status"] == "failed"
    assert after["preview"]["error_code"] == "PREVIEW_UNSUPPORTED"
    assert "complex-valued" in after["preview"]["error_message"]
    assert after["status"] == "validated"

    response, _ = preview(client, asset["id"])
    assert response.status_code == 404 and response.json()["code"] == "PREVIEW_NOT_AVAILABLE"
    assert "complex-valued" in response.json()["detail"]
    assert artifacts(asset["id"]) == {}

    job = client.get(f"/api/v1/jobs/{after['preview']['job_id']}").json()
    assert (job["status"], job["attempt"], job["error"]["code"]) == ("failed", 1, "PREVIEW_UNSUPPORTED")  # not retried


# --- video -----------------------------------------------------------------------------------------------------------


@needs_ffmpeg
@pytest.mark.parametrize("ext", ["mp4", "mov", "mkv"])
def test_video_preview_is_one_decoded_frame(client, project, headers, run_jobs, tmp_path, ext):
    data = media.make_video(tmp_path / f"clip.{ext}")
    asset = upload(client, project, headers, f"clip.{ext}", data, "video").json()["asset"]
    assert run_jobs() == ["completed"]
    _, view = preview(client, asset["id"])
    assert view.size == (64, 48)
    details = artifacts(asset["id"])["view"][5]
    assert "frame_time_requested_s" in details and "not a summary" in details["note"]
    assert list(store.uploads_dir().glob("*")) == []  # the temporary frame file is removed


# --- API integration ----------------------------------------------------------------------------------------------------


def test_preview_can_be_regenerated_through_the_api(client, project, headers, run_jobs):
    asset = upload(client, project, headers, "p.png", media.image_bytes("PNG")).json()["asset"]
    url = f"/api/v1/projects/{project['id']}/jobs"
    body = {"kind": "preview", "asset_id": asset["id"]}

    duplicate = client.post(url, json=body, headers=headers)  # the automatic one is still queued
    assert duplicate.status_code == 409 and duplicate.json()["code"] == "JOB_ALREADY_ACTIVE"
    run_jobs()
    first = artifacts(asset["id"])["view"]

    again = client.post(url, json=body, headers=headers)
    assert again.status_code == 202 and again.json()["status"] == "queued"
    # While the new one is pending, the existing preview is still served.
    assert client.get(f"/api/v1/assets/{asset['id']}").json()["preview"]["status"] == "pending"
    assert preview(client, asset["id"])[0].status_code == 200
    assert run_jobs() == ["completed"]
    assert artifacts(asset["id"])["view"][4] == first[4]  # deterministic: same picture, same checksum
    assert len(artifacts(asset["id"])) == 2  # replaced, not accumulated

    listing = client.get(f"/api/v1/projects/{project['id']}/assets").json()["items"]
    assert listing[0]["preview"]["status"] == "ready"
    assert preview(client, asset["id"], "huge")[0].status_code == 422
    assert client.get("/api/v1/assets/00000000-0000-4000-8000-000000000000/preview").status_code == 404


def test_derived_files_can_never_be_registered_among_the_originals(client, project, headers, run_jobs):
    asset = upload(client, project, headers, "p.png", media.image_bytes("PNG")).json()["asset"]
    run_jobs()
    with get_engine().begin() as conn, pytest.raises(Exception, match="ck_artifact_not_an_original"):
        conn.execute(
            text("UPDATE artifact SET storage_path = 'originals/aa/bb/x' WHERE asset_id = :id"), {"id": asset["id"]}
        )


# --- large files --------------------------------------------------------------------------------------------------------

MEASURE = """
import ctypes, json, sys
from ctypes import wintypes
from pathlib import Path
from geopoc.previews.generate import render_raster

class Counters(ctypes.Structure):
    _fields_ = [("cb", wintypes.DWORD), ("PageFaultCount", wintypes.DWORD)] + [
        (name, ctypes.c_size_t) for name in (
            "PeakWorkingSetSize", "WorkingSetSize", "QuotaPeakPagedPoolUsage", "QuotaPagedPoolUsage",
            "QuotaPeakNonPagedPoolUsage", "QuotaNonPagedPoolUsage", "PagefileUsage", "PeakPagefileUsage")]

def peak_mb():
    counters = Counters(); counters.cb = ctypes.sizeof(counters)
    kernel = ctypes.WinDLL("kernel32"); kernel.GetCurrentProcess.restype = wintypes.HANDLE
    psapi = ctypes.WinDLL("psapi")
    psapi.GetProcessMemoryInfo.argtypes = [wintypes.HANDLE, ctypes.POINTER(Counters), wintypes.DWORD]
    psapi.GetProcessMemoryInfo(kernel.GetCurrentProcess(), ctypes.byref(counters), counters.cb)
    return counters.PeakWorkingSetSize / 1024**2

before = peak_mb()
rendered = render_raster(Path(sys.argv[1]))
print(json.dumps({"before": before, "peak": peak_mb(), "size": rendered.image.size, "details": rendered.details}))
"""


@pytest.mark.skipif(sys.platform != "win32", reason="measures peak working set through the Windows API")
def test_large_raster_preview_is_memory_bounded():
    """A 400 MB raster is previewed in a fresh process whose peak memory is measured by the operating system."""
    path = TEST_DATA_ROOT / "large_test.tif"
    path.parent.mkdir(parents=True, exist_ok=True)
    side = 20_000
    if shutil.disk_usage(path.parent).free < 3 * 1024**3:
        pytest.skip("not enough free disk space for the 400 MB fixture")
    rng = np.random.default_rng(0)
    with rasterio.open(
        path, "w", driver="GTiff", width=side, height=side, count=1, dtype="uint8",
        crs="EPSG:32643", transform=from_origin(500000, 3000000, 1, 1), tiled=True, blockxsize=512, blockysize=512,
    ) as dst:  # fmt: skip
        for row in range(0, side, 2000):
            dst.write(rng.integers(0, 255, (1, 2000, side), dtype=np.uint8), window=Window(0, row, side, 2000))
    file_mb = path.stat().st_size / 1024**2
    assert file_mb > 380

    done = subprocess.run(
        [sys.executable, "-c", MEASURE, str(path)], cwd=API_DIR, capture_output=True, text=True, check=True
    )
    result = json.loads(done.stdout.strip().splitlines()[-1])
    path.unlink()

    assert result["size"] == [1280, 1280]
    assert result["details"]["resampling"] == "nearest"  # 400 million pixels: sampled, not averaged
    growth = result["peak"] - result["before"]
    # The whole raster would need 400 MB. The preview must stay far below that.
    assert growth < 150, f"preview used {growth:.0f} MB above the {result['before']:.0f} MB baseline"
    assert result["peak"] < file_mb
